from common import *
from modelo_mezcla_conjunta import JointRouteTimeMixture
import torch
B,K,J=3,2,8;torch.manual_seed(1729);weights=torch.randn(B,K,J,requires_grad=True).log_softmax(-1);component=torch.randn(B,K,J,116,requires_grad=True).log_softmax(-1);logp=torch.logsumexp(weights[...,None]+component,-2);loc=torch.randn(B,K,J,14,requires_grad=True);scale=torch.full_like(loc,.3,requires_grad=True);output=(logp,weights,loc,scale,component);target=torch.tensor([60.,600.,1785.]);geometry=torch.randn(B,14);mask=torch.ones(B)
class Probe:pass
probe=Probe();probe.duration_grid=torch.arange(60,1786,15.);score=JointRouteTimeMixture.geometry_score(probe,output,target,geometry,mask);assert torch.isfinite(score);score.backward();assert loc.grad.abs().sum()>0 and torch.isfinite(loc.grad).all() and torch.isfinite(scale.grad).all();assert abs(float(JointRouteTimeMixture.geometry_score(probe,output,target,geometry,torch.zeros(B))))<1e-8
permutation=torch.tensor([7,0,6,1,5,2,4,3]);permuted=(logp,weights[:,:,permutation],loc[:,:,permutation],scale[:,:,permutation],component[:,:,permutation]);s2=JointRouteTimeMixture.geometry_score(probe,permuted,target,geometry,mask);assert abs(float(score.detach()-s2.detach()))<1e-5;q=JointRouteTimeMixture.quantiles(probe,logp.detach());assert torch.all(q[:,0]<=q[:,1]) and torch.all(q[:,1]<=q[:,2]);assert (logp.exp().sum(-1)-1).abs().max()<1e-5
write_json(BASE/'instrumentos/mezcla_conjunta_contrato.json',dict(passed=True,finite_gradients=True,masked_geometry_zero_loss=True,component_permutation_invariant=True,normalized_time_distribution=True,ordered_quantiles=True,conditional_geometry_nll_divided_after_component_marginalization=True,observed_geometry_not_forward_input=True,test_labels_read=False));print('Joint route-time contracts passed',flush=True)
